import csv
from io import StringIO

def total_minutes(values):
    if any(value < 0 for value in values):
        raise ValueError('Minutes cannot be negative')
    return sum(values)

def import_sessions(text):
    reader = csv.DictReader(StringIO(text))
    if reader.fieldnames is None or not {'lesson', 'minutes'} <= set(reader.fieldnames):
        raise ValueError('CSV needs lesson and minutes columns')
    result = []
    for row_number, row in enumerate(reader, start=2):
        lesson = row['lesson']
        try:
            minutes = int(row['minutes'])
        except (TypeError, ValueError) as error:
            raise ValueError(f'Row {row_number}: invalid minutes') from error
        if not lesson or not lesson.strip() or minutes < 0:
            raise ValueError(f'Row {row_number}: invalid session')
        result.append((lesson.strip(), minutes))
    return result

def summary(text):
    sessions = import_sessions(text)
    return {'sessions': len(sessions), 'minutes': total_minutes([m for _, m in sessions])}

print(summary('lesson,minutes\nloops,20\nfiles,35\n'))

