def total_minutes(values):
    if any(value < 0 for value in values):
        raise ValueError('Minutes cannot be negative')
    return sum(values)

def summary(sessions):
    return {
        'sessions': len(sessions),
        'minutes': total_minutes([minutes for _, minutes in sessions]),
    }

assert summary([('loops', 20), ('files', 35)]) == {'sessions': 2, 'minutes': 55}
assert summary([]) == {'sessions': 0, 'minutes': 0}
